#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include <string.h>

#define WASM_PAGE_SIZE 65536
#define WASM_MAX_PAGES 16
#define WASM_MAX_TABLE_SLOTS 64
#define WASM_GUARD_SIZE 4096

typedef enum {
    PAGE_STATE_UNMAPPED = 0,
    PAGE_STATE_MAPPED = 1,
    PAGE_STATE_GUARD = 2
} page_state_t;

typedef enum {
    WASM_OP_LOAD32 = 1,
    WASM_OP_STORE32 = 2,
    WASM_OP_LOAD64 = 3,
    WASM_OP_STORE64 = 4,
    WASM_OP_CALL_INDIRECT = 5
} wasm_opcode_t;

typedef struct {
    wasm_opcode_t opcode;
    uint32_t base_addr;
    uint32_t offset;
    uint64_t value;
    uint32_t table_idx;
} wasm_insn_t;

typedef struct {
    bool is_valid;
    uint64_t type_signature;
    uint32_t target_code_id;
} table_slot_t;

typedef struct {
    uint8_t linear_memory[WASM_MAX_PAGES * WASM_PAGE_SIZE];
    page_state_t page_states[WASM_MAX_PAGES];
    uint32_t current_memory_bytes;
    table_slot_t table_slots[WASM_MAX_TABLE_SLOTS];
    bool is_initialized;
} wasm_sandbox_t;

void wasm_init_sandbox(wasm_sandbox_t *box, uint32_t initial_pages) {
    if (!box) return;
    box->is_initialized = true;
    if (initial_pages == 0) initial_pages = 1;
    if (initial_pages > WASM_MAX_PAGES) initial_pages = WASM_MAX_PAGES;
    box->current_memory_bytes = initial_pages * WASM_PAGE_SIZE;

    for (uint32_t i = 0; i < initial_pages; i++) {
        box->page_states[i] = PAGE_STATE_MAPPED;
        memset(box->linear_memory + i * WASM_PAGE_SIZE, 0, WASM_PAGE_SIZE);
    }
    for (uint32_t i = initial_pages; i < WASM_MAX_PAGES; i++) {
        box->page_states[i] = PAGE_STATE_GUARD;
    }
    for (uint32_t i = 0; i < WASM_MAX_TABLE_SLOTS; i++) {
        box->table_slots[i].is_valid = false;
        box->table_slots[i].type_signature = 0;
        box->table_slots[i].target_code_id = 0;
    }
}

int wasm_register_table_slot(wasm_sandbox_t *box, uint32_t slot_idx, uint64_t type_sig, uint32_t target_id) {
    if (!box || !box->is_initialized || slot_idx >= WASM_MAX_TABLE_SLOTS) return -1;
    if (box->table_slots[slot_idx].is_valid) return -2;
    box->table_slots[slot_idx].is_valid = true;
    box->table_slots[slot_idx].type_signature = type_sig;
    box->table_slots[slot_idx].target_code_id = target_id;
    return 0;
}

int wasm_verify_mem_op(const wasm_sandbox_t *box, uint32_t base, uint32_t offset, uint32_t access_size, uint32_t align_mask) {
    if (!box || !box->is_initialized) return -1;
    if (((base + offset) & align_mask) != 0) return -3;

    uint32_t addr = base + offset;
    if (addr < base) return -4;

    uint32_t end_addr = addr + access_size;
    if (end_addr < addr) return -4;

    if ((uint64_t)base + offset + access_size > box->current_memory_bytes) {
        uint64_t target_addr = (uint64_t)base + offset;
        uint64_t page_idx = target_addr / WASM_PAGE_SIZE;
        if (page_idx < WASM_MAX_PAGES && box->page_states[page_idx] == PAGE_STATE_GUARD) {
            return -5;
        }
        return -6;
    }
    return 0;
}

int wasm_execute_instruction(wasm_sandbox_t *box, const wasm_insn_t *insn, uint64_t *out_result) {
    if (!box || !insn || !out_result) return -1;
    switch (insn->opcode) {
        case WASM_OP_LOAD32: {
            int err = wasm_verify_mem_op(box, insn->base_addr, insn->offset, 4, 3);
            if (err < 0) return err;
            uint32_t val;
            memcpy(&val, box->linear_memory + insn->base_addr + insn->offset, 4);
            *out_result = (uint64_t)val;
            return 0;
        }
        case WASM_OP_STORE32: {
            int err = wasm_verify_mem_op(box, insn->base_addr, insn->offset, 4, 3);
            if (err < 0) return err;
            uint32_t val = (uint32_t)insn->value;
            memcpy(box->linear_memory + insn->base_addr + insn->offset, &val, 4);
            return 0;
        }
        case WASM_OP_LOAD64: {
            int err = wasm_verify_mem_op(box, insn->base_addr, insn->offset, 8, 7);
            if (err < 0) return err;
            uint64_t val;
            memcpy(&val, box->linear_memory + insn->base_addr + insn->offset, 8);
            *out_result = val;
            return 0;
        }
        case WASM_OP_STORE64: {
            int err = wasm_verify_mem_op(box, insn->base_addr, insn->offset, 8, 7);
            if (err < 0) return err;
            uint64_t val = insn->value;
            memcpy(box->linear_memory + insn->base_addr + insn->offset, &val, 8);
            return 0;
        }
        case WASM_OP_CALL_INDIRECT: {
            if (insn->table_idx >= WASM_MAX_TABLE_SLOTS) return -7;
            if (!box->table_slots[insn->table_idx].is_valid) return -8;
            if (box->table_slots[insn->table_idx].type_signature != insn->value) return -9;
            *out_result = box->table_slots[insn->table_idx].target_code_id;
            return 0;
        }
        default:
            return -1;
    }
}

int wasm_grow_memory(wasm_sandbox_t *box, uint32_t delta_pages) {
    if (!box || !box->is_initialized) return -1;
    uint32_t curr_pages = box->current_memory_bytes / WASM_PAGE_SIZE;
    if (curr_pages + delta_pages > WASM_MAX_PAGES) return -10;

    for (uint32_t i = curr_pages; i < curr_pages + delta_pages; i++) {
        box->page_states[i] = PAGE_STATE_MAPPED;
        memset(box->linear_memory + i * WASM_PAGE_SIZE, 0, WASM_PAGE_SIZE);
    }

    box->current_memory_bytes += delta_pages * WASM_PAGE_SIZE;
    return curr_pages;
}
